import { streamText, stepCountIs, type ToolSet } from 'ai';
import { createOpenAI } from '@ai-sdk/openai';
import { db } from './firebase';
import { getAvailableTools } from './pipelines/edu-video/index';
import { loadAgentMd, loadSkillMd, resolveSkill } from './skills/loader';
import { ensureSession, getRecentMessages, writeMessage } from './session';

const openrouter = createOpenAI({
  baseURL: 'https://openrouter.ai/api/v1',
  apiKey: process.env.OPENROUTER_API_KEY ?? '',
});

function getLastMessageText(messages: any[]): string {
  if (messages.length === 0) return '';

  const last = messages[messages.length - 1];

  if (typeof last.content === 'string') {
    return last.content;
  }

  if (Array.isArray(last.parts)) {
    return last.parts
      .filter((part: { type: string }) => part.type === 'text')
      .map((part: { text: string }) => part.text)
      .join('');
  }

  return '';
}

function appendVideoContext(
  systemPrompt: string,
  sessionData: Record<string, unknown> | undefined
): string {
  if (!sessionData?.videoUrl) return systemPrompt;

  const name = sessionData.videoName ? ` (${sessionData.videoName})` : '';
  return (
    systemPrompt +
    `\n\nThe user has uploaded a teacher video${name} and it is ready for processing. Do not ask whether they have a video file.`
  );
}

export async function handleChat(
  messages: any[],
  userId: string,
  sessionId: string,
  model?: string,
  videoUrl?: string,
  pipelineMode?: 'ask' | 'auto',
  skillId?: string,
  videoName?: string
) {
  const lastUserText = getLastMessageText(messages);
  const title = lastUserText.trim().slice(0, 50);

  await ensureSession(sessionId, userId, title);

  await db.collection('sessions').doc(sessionId).set(
    {
      pipelineMode: pipelineMode ?? 'auto',
      ...(videoUrl ? { videoUrl, ...(videoName ? { videoName } : {}) } : {}),
    },
    { merge: true }
  );

  const sessionSnap = await db.collection('sessions').doc(sessionId).get();
  let sessionData = sessionSnap.data();
  const effectiveVideoUrl =
    videoUrl ?? (sessionData?.videoUrl as string | undefined);
  const effectiveVideoName =
    videoName ?? (sessionData?.videoName as string | undefined);

  await writeMessage(
    sessionId,
    'user',
    lastUserText,
    videoUrl ? { videoUrl, videoName } : undefined
  );

  const history = await getRecentMessages(sessionId, 50);

  const selectedModel = model ?? 'anthropic/claude-haiku-4-5';

  let pipelinePhase: number = sessionData?.pipelinePhase ?? 0;
  let isEduVideoActive = pipelinePhase >= 2 && pipelinePhase <= 6;
  const resolvedSkill = resolveSkill(messages, skillId);
  const isEduVideoStart = !isEduVideoActive && resolvedSkill === 'edu-video';

  if (isEduVideoStart) {
    if (effectiveVideoUrl) {
      await db.collection('sessions').doc(sessionId).set(
        {
          pipelinePhase: 2,
          pipelineStatus: 'running',
          pipelineMode: pipelineMode ?? 'auto',
          videoUrl: effectiveVideoUrl,
        },
        { merge: true }
      );
      pipelinePhase = 2;
      isEduVideoActive = true;
    }
  }

  const historyMessages = history.map((msg) => ({
    role: msg.role as 'user' | 'assistant',
    content: msg.content,
  }));

  if (isEduVideoActive) {
    if (sessionData?.pipelineStatus === 'awaiting_approval') {
      await db.collection('sessions').doc(sessionId).set(
        { pipelineStatus: 'running', pipelineApproved: true, pipelinePhase: 4 },
        { merge: true }
      );
      const refreshed = await db.collection('sessions').doc(sessionId).get();
      sessionData = refreshed.data() ?? {};
      pipelinePhase = 4;
    }

    const phaseTools = getAvailableTools(pipelinePhase, sessionData ?? {});
    const skillMd = loadSkillMd('edu-video');
    const sessionVideoUrl = effectiveVideoUrl ?? (sessionData?.videoUrl as string | undefined) ?? '';
    const fullSystem = appendVideoContext(
      loadAgentMd() +
        '\n\n' +
        skillMd +
        `\n\nPipeline context: sessionId=${sessionId}, videoUrl=${sessionVideoUrl}, pipelineMode=${sessionData?.pipelineMode ?? 'auto'}`,
      { ...sessionData, videoUrl: sessionVideoUrl }
    );

    const result = streamText({
      model: openrouter.chat(selectedModel),
      system: fullSystem,
      messages: historyMessages,
      tools: Object.keys(phaseTools).length > 0 ? (phaseTools as ToolSet) : undefined,
      stopWhen: stepCountIs(20),
      onError: ({ error }) => {
        console.error('streamText error:', error);
      },
    });

    void result.text.then(
      (text) => writeMessage(sessionId, 'assistant', text),
      (error: unknown) => {
        console.error('Failed to persist assistant message:', error);
      }
    );

    return result;
  }

  let fullSystemPrompt = loadAgentMd();

  if (resolvedSkill) {
    const skillContent = loadSkillMd(resolvedSkill);
    if (skillContent) {
      fullSystemPrompt = `${fullSystemPrompt}\n\n${skillContent}`;
    }
  }

  fullSystemPrompt = appendVideoContext(fullSystemPrompt, {
    ...sessionData,
    videoUrl: effectiveVideoUrl ?? sessionData?.videoUrl,
  });

  if (isEduVideoStart && !effectiveVideoUrl) {
    fullSystemPrompt +=
      '\n\nThe user invoked edu-video but no video has been uploaded yet. Ask them to upload a teacher video before starting the pipeline.';
  }

  const result = streamText({
    model: openrouter.chat(selectedModel),
    system: fullSystemPrompt,
    messages: historyMessages,
    onError: ({ error }) => {
      console.error('streamText error:', error);
    },
  });

  void result.text.then(
    (text) => writeMessage(sessionId, 'assistant', text),
    (error: unknown) => {
      console.error('Failed to persist assistant message:', error);
    }
  );

  return result;
}
